$body = @{ email="admin@example.com"; password="password"; subdomain="test15" } | ConvertTo-Json; $resp = Invoke-RestMethod -Uri http://localhost:8080/api/v1/auth/login -Method Post -Body $body -ContentType "application/json"; $token = $resp.token; $headers = @{ Authorization = "Bearer $token" }; try { $prod = Invoke-RestMethod -Uri http://localhost:8080/api/v1/products -Headers $headers -Method Get; echo "SUCCESS"; echo $prod } catch { echo "Error: $($_.Exception.Response.StatusCode)" }
